{!REQUIRESCRIPT("/soap/ajax/29.0/connection.js")}

var c = new sforce.SObject("Case"); 
var currentCase = sforce.connection.query("SELECT Subject, Description FROM Case WHERE Id = '{!Case.Id}'");
var records = currentCase.getArray("records");

c.Id = "{!Case.Id}"; 
c.Status = "Closed: SPAM";
c.Subject = "SPAM: " + records[0].Subject;
c.Description = "SPAM: " + records[0].Description;

sforce.connection.update([c]);
window.location = window.location.href;
